                    iy >= 0 && iy < IH &&
                    ix >= 0 && ix < IW) {
                    value = gX(n, ic_global, iz, iy, ix);
                }
            }
            sX(ic_local, lz_s, ly_s, lx_s) = value;
        }
        __syncthreads();
        const int ic_count = min(IC_TILE, IC - ic0);
        if (oz < OD && oy < OH) {
            for (int ic_local = 0; ic_local < ic_count; ++ic_local) {
                const int ic_global = ic0 + ic_local;
                for (int kz = 0; kz < K; ++kz) {
                    const int sxz = lz + (K - 1 - kz);
                    for (int ky = 0; ky < K; ++ky) {
                        const int sxy = ly + (K - 1 - ky);
                        for (int kx = 0; kx < K; ++kx) {
                            const int sxx0 = lx + (K - 1 - kx);
                            const int sxx1 = lx + TILE + (K - 1 - kx);
                            const int sxx2 = lx + 2 * TILE + (K - 1 - kx);
                            const int sxx3 = lx + 3 * TILE + (K - 1 - kx);
                            for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
                                const int oc = oc0 + oc_local;
                                if (oc < OC) {
                                    const float w = gW(ic_global, oc, kz, ky, kx);
                                    if (ox0_thread < OW) acc0[oc_local] += sX(ic_local, sxz, sxy, sxx0) * w;
                                    if (ox1_thread < OW) acc1[oc_local] += sX(ic_local, sxz, sxy, sxx1) * w;
                                    if (ox2_thread < OW) acc2[oc_local] += sX(ic_local, sxz, sxy, sxx2) * w;
                                    if (ox3_thread < OW) acc3[oc_local] += sX(ic_local, sxz, sxy, sxx3) * w;
                                }
                            }
                        }
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    if (oz < OD && oy < OH) {
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
            const int oc = oc0 + oc_local;
            if (oc < OC) {
                if (ox0_thread < OW) gY(n, oc, oz, oy, ox0_thread) = acc0[oc_local];
                if (ox1_thread < OW) gY(n, oc, oz, oy, ox1_thread) = acc1[oc_local];
                if (ox2_thread < OW) gY(n, oc, oz, oy, ox2_thread) = acc2[oc_local];
                if (ox3_thread < OW) gY(n, oc, oz, oy, ox3_thread) = acc3[oc_local];
            }
        }
    }
}
}


