    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must have shape [N, IC, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [IC, OC, K, K, K]");

    if (bias.has_value()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->scalar_type() == at::kFloat, "bias must be float32");
        TORCH_CHECK(bias->dim() == 1, "bias must be 1D");
        TORCH_CHECK(bias->device() == x.device(),
                    "bias must be on the same CUDA device as x");
    }

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    const int N = static_cast<int>(xc.size(0));
    const int IC = static_cast<int>(xc.size(1));
    const int ID = static_cast<int>(xc.size(2));
    const int IH = static_cast<int>(xc.size(3));
    const int IW = static_cast<int>(xc.size(4));

    const int weight_ic = static_cast<int>(wc.size(0));
    const int OC = static_cast<int>(wc.size(1));
    const int K = static_cast<int>(wc.size(2));

     TORCH_CHECK(x.device() == weight.device(),
                 "x and weight must be on the same CUDA device");
    TORCH_CHECK(weight_ic == IC, "weight.size(0) must equal x.size(1)");
     TORCH_CHECK(K > 0 && wc.size(3) > 0 && wc.size(4) > 0,
                 "kernel dimensions must be positive");
     TORCH_CHECK(wc.size(2) == wc.size(3) && wc.size(2) == wc.size(4),
                 "only cubic kernels are supported");

    if (bias.has_value()) {
        TORCH_CHECK(bias->size(0) == OC, "bias size mismatch");
    }

    const int OD = ID + K - 1;
    const int OH = IH + K - 1;
    const int OW = IW + K - 1;

    auto yc = torch::empty({N, OC, OD, OH, OW}, xc.options());

    torch::Tensor bc;
    const float* b_ptr = nullptr;
    bool has_bias = false;

