template <int TILE, int IC_TILE, int OC_TILE>
void launch_cute_transpose3d(
    const torch::Tensor& xc,
    const torch::Tensor& wc,
    const torch::Tensor& bc,
    torch::Tensor& yc,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int K,
    int OD,
    int OH,
    int OW,
    bool has_bias,
    cudaStream_t stream)
