    constexpr int TILE_Z = TILE / 2;
    constexpr int THREADS = TILE * TILE_Y * TILE_Z;
    const int oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
    const int z_tiles = (OD + TILE_Z - 1) / TILE_Z;
    dim3 block(THREADS);
    dim3 grid(
        (OW + TILE_X - 1) / TILE_X,
        (OH + TILE_Y - 1) / TILE_Y,
        N * z_tiles * oc_tiles);
    const int shared_x = TILE_X + K - 1;
    const int shared_y = TILE_Y + K - 1;
    const int shared_z = TILE_Z + K - 1;
    const size_t smem_bytes =
        static_cast<size_t>(IC_TILE) *
